package com.bank.linkedlist;

import org.springframework.stereotype.Service;

@Service
public class MiddleElementService {

    // Simple singly-linked list node
    public static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
        ListNode(int val, ListNode next) { this.val = val; this.next = next; }
    }

    // ═══ SLOW/FAST POINTER — find middle ═══
    public int findMiddle(ListNode head) {
        if (head == null) throw new IllegalArgumentException("Empty list");

        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;          // move 1 step
            fast = fast.next.next;     // move 2 steps
        }
        // When fast reaches end, slow is at middle
        return slow.val;
    }

    // Helper to build linked list from array
    public ListNode buildList(int... values) {
        if (values.length == 0) return null;
        ListNode head = new ListNode(values[0]);
        ListNode current = head;
        for (int i = 1; i < values.length; i++) {
            current.next = new ListNode(values[i]);
            current = current.next;
        }
        return head;
    }
}
