package com.bank.linkedlist;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class MiddleElementTest {

    MiddleElementService service = new MiddleElementService();

    @Test void oddLength() {
        var head = service.buildList(1, 2, 3, 4, 5);
        assertThat(service.findMiddle(head)).isEqualTo(3);  // [1,2,**3**,4,5]
    }

    @Test void evenLength() {
        var head = service.buildList(1, 2, 3, 4);
        assertThat(service.findMiddle(head)).isEqualTo(3);  // [1,2,**3**,4] — second middle
    }

    @Test void singleElement() {
        var head = service.buildList(42);
        assertThat(service.findMiddle(head)).isEqualTo(42);
    }

    @Test void twoElements() {
        var head = service.buildList(10, 20);
        assertThat(service.findMiddle(head)).isEqualTo(20);  // second of two middles
    }

    @Test void emptyListThrows() {
        assertThatThrownBy(() -> service.findMiddle(null))
            .isInstanceOf(IllegalArgumentException.class);
    }
}
