package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class MiddleOfListTest {

    static class Node { int val; Node next; Node(int v){ val = v; } }

    int middle(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;          // 1 step
            fast = fast.next.next;     // 2 steps
        }
        return slow.val;
    }

    @Test
    void slowFastFindsMiddle() {
        Node a = new Node(10), b = new Node(20), c = new Node(30),
             d = new Node(40), e = new Node(50);
        a.next = b; b.next = c; c.next = d; d.next = e; // 10->20->30->40->50

        assertThat(middle(a)).isEqualTo(30);
    }
}
